#BUisness queryies

/*CSV File	SQL Table	Key Columns
-- customers.csv-	customers	customer_id, name, nationality, occupation, risk_score
accounts.csv-       accounts	account_id, customer_id, account_type, open_date
transactions.csv-	transactions	transaction_id, from_account, to_account, amount, timestamp, channel, label
Relationships:

accounts.customer_id → customers.customer_id

transactions.from_account → accounts.account_id

transactions.to_account → accounts.account_id*/

-- Customers table: Show all columns for the first 10 customers.
       select * from customers order by customer_id asc limit 10;

-- Customers table: List only customer_id and name of customers who are 'unemployed'.
            select customer_id,name ,occupation from customers where occupation='unemployed';
-- Customers table: Count the total number of customers.
         select count(customer_id) from customers;
-- Customers table: Find all customers with risk_score greater than 80.
            select customer_id,name,risk_score from customers where risk_score>80;
-- Accounts table: Show all accounts of type 'business'.
        select * from accounts where account_type='business';
-- Accounts table: Count how many accounts each customer has (customer_id appears multiple times).
SELECT customer_id,
       COUNT(*) AS account_count
FROM accounts
GROUP BY customer_id;
-- Accounts table: List account IDs opened before '2022-01-01'.
         select account_id ,open_date from accounts where open_date<'2022-01-01';
-- Transactions table: Show the first 20 transactions ordered by amount descending.
				select transaction_id,amount from transactions order by amount desc limit 20;

-- Transactions table: Find all transactions with amount exactly 9000 (unlikely, but practice).
              select transaction_id,amount from transactions where amount='9000';
-- Transactions table: Count how many transactions have channel = 'wire'.
         select transaction_id,channel from transactions where channel='wire';
-- Transactions table: List distinct channel values.
       select distinct(channel) from transactions;
-- Transactions table: Find transactions where from_account is 'ACC_0001'.
         select transaction_id,from_account from transactions where from_account='ACC_0001';
-- 📙 MEDIUM Questions (Two Tables – Learn JOINs)
-- These require joining two tables using JOIN. Usually you’ll join transactions with accounts 
-- (to get account details) or accounts with customers (to get customer info).
         
-- Join transactions + accounts (sender): Show each transaction with the sender’s account_type.
            select t.transaction_id ,
    t.from_account,
    a.account_type AS sender_account_type,
    t.to_account,
    t.amount,
    t.timestamp,
    t.channel,
    t.label
FROM transactions t
JOIN accounts a ON t.from_account = a.account_id;
-- Join transactions + accounts (receiver): Show each transaction with the receiver’s account_type.
             SELECT 
    t.transaction_id,
    t.from_account,
    t.to_account,
    a.account_type AS receiver_account_type,
    t.amount,
    t.timestamp,
    t.channel,
    t.label
FROM transactions t
JOIN accounts a ON t.to_account = a.account_id;

-- Join accounts + customers: List all accounts with the customer’s name and occupation.
SELECT 
    a.account_id,
    a.customer_id,
    a.account_type,
    a.open_date,
    c.name AS customer_name,
    c.occupation
FROM accounts a
JOIN customers c ON a.customer_id = c.customer_id;
-- Join accounts + customers: Find accounts belonging to customers with occupation = 'student'.
SELECT 
    a.account_id,
    a.customer_id,
    a.account_type,
    a.open_date,
    c.name AS customer_name,
    c.occupation
FROM accounts a
JOIN customers c ON a.customer_id = c.customer_id
WHERE c.occupation = 'student';
-- Join transactions + accounts + customers (three tables): Show transaction_id, amount, sender’s account_type, and sender’s customer name.
       SELECT 
    t.transaction_id,
    t.amount,
    sender.account_type AS sender_account_type,
    sender_customer.name AS sender_customer_name
FROM transactions t
JOIN accounts sender ON t.from_account = sender.account_id
JOIN customers sender_customer ON sender.customer_id = sender_customer.customer_id;
-- Join transactions + accounts + customers (three tables): Show transaction_id, receiver’s account_type, and receiver’s customer name.
             SELECT 
    t.transaction_id,
    t.amount,
    receiver.account_type AS receiver_account_type,
    receiver_customer.name AS receiver_customer_name
FROM transactions t
JOIN accounts receiver ON t.to_account = receiver.account_id
JOIN customers receiver_customer ON receiver.customer_id = receiver_customer.customer_id;
-- Join transactions + accounts (sender): Find the total amount sent by each account_type (group by account_type).
    SELECT 
    sender.account_type,
    SUM(t.amount) AS total_amount_sent
FROM transactions t
JOIN accounts sender ON t.from_account = sender.account_id
GROUP BY sender.account_type;

-- Join transactions + accounts (receiver): Find the average transaction amount received by savings accounts.
SELECT 
    AVG(t.amount) AS avg_amount_received
FROM transactions t
JOIN accounts receiver ON t.to_account = receiver.account_id
WHERE receiver.account_type = 'savings';

#HARD Questions (Multiple Tables + Aggregations + Subqueries)
-- These mimic real AML analytics. They may involve GROUP BY, HAVING, CASE, subqueries, or window functions.

-- Structuring detection: For each from_account, count how many transactions are between 8000 and 9900. Show only accounts with more than 2 such transactions.
      SELECT 
    from_account,
    COUNT(*) AS structuring_tx_count,
    SUM(amount) AS total_structured_amount
FROM transactions
WHERE amount BETWEEN 8000 AND 9900
GROUP BY from_account
HAVING COUNT(*) > 2
ORDER BY structuring_tx_count DESC;
-- Velocity: Find accounts that sent more than 5 transactions in a single day (use date(timestamp) to group by day).
           SELECT 
    from_account,
    date(timestamp) AS transaction_date,
    COUNT(*) AS tx_count
FROM transactions
GROUP BY from_account, date(timestamp)
HAVING COUNT(*) > 5
ORDER BY tx_count DESC;
-- Fan‑out analysis: For each account, count how many distinct to_account (receivers) it has. Show top 5.
SELECT 
    from_account,
    COUNT(DISTINCT to_account) AS distinct_receivers
FROM transactions
GROUP BY from_account
ORDER BY distinct_receivers DESC
LIMIT 5;
-- Mule → Master pattern: Find accounts that received money from more than 3 different senders, all sending amounts between 8000 and 9900.
SELECT 
    to_account,
    COUNT(DISTINCT from_account) AS num_distinct_senders,
    SUM(amount) AS total_received
FROM transactions
WHERE amount BETWEEN 8000 AND 9900
GROUP BY to_account
HAVING COUNT(DISTINCT from_account) > 3
ORDER BY num_distinct_senders DESC;
-- Customer risk: For each customer, compute total amount they sent (SUM(t.amount) across all their accounts) and the number of transactions. Show customers with total sent > 100000.
SELECT 
    c.customer_id,
    c.name AS customer_name,
    COUNT(t.transaction_id) AS num_transactions_sent,
    SUM(t.amount) AS total_amount_sent
FROM customers c
JOIN accounts a ON c.customer_id = a.customer_id
JOIN transactions t ON a.account_id = t.from_account
GROUP BY c.customer_id, c.name
HAVING SUM(t.amount) > 100000
ORDER BY total_amount_sent DESC;
-- Account age vs activity: Find accounts opened after '2023-01-01' that have already sent more than 10 transactions.
SELECT 
    a.account_id,
    a.open_date,
    COUNT(t.transaction_id) AS sent_tx_count
FROM accounts a
JOIN transactions t ON a.account_id = t.from_account
WHERE a.open_date > '2023-01-01'
GROUP BY a.account_id, a.open_date
HAVING COUNT(t.transaction_id) > 10
ORDER BY sent_tx_count DESC;
-- -- Circular flows: Find pairs of accounts where A sent to B and B sent to A within the same week. (Hint: self‑join).
SELECT 
    t1.from_account AS account_a,
    t1.to_account AS account_b,
    t1.timestamp AS a_to_b_time,
    t2.timestamp AS b_to_a_time
FROM transactions t1
JOIN transactions t2 
    ON t1.from_account = t2.to_account 
    AND t1.to_account = t2.from_account
WHERE t1.transaction_id < t2.transaction_id
  AND ABS(DATEDIFF(t1.timestamp, t2.timestamp)) <= 7
ORDER BY t1.from_account, t1.to_account;
-- Weekend anomaly: Count transactions by day of week (strftime('%w', timestamp) for SQLite) and find the day with the most activity for a specific account.
SELECT 
    DAYOFWEEK(timestamp) AS day_of_week,  -- 1=Sunday, 2=Monday, ..., 7=Saturday
    DAYNAME(timestamp) AS day_name,
    COUNT(*) AS transaction_count
FROM transactions
WHERE from_account = 'ACC_0001'
GROUP BY day_of_week, day_name
ORDER BY transaction_count DESC
LIMIT 1;
-- CTR trigger: List all transactions with amount > 10000 and include sender/receiver account types and customer names.
SELECT 
    t.transaction_id,
    t.amount,
    t.timestamp,
    sender.account_type AS sender_account_type,
    sender_customer.name AS sender_customer_name,
    receiver.account_type AS receiver_account_type,
    receiver_customer.name AS receiver_customer_name
FROM transactions t
JOIN accounts sender ON t.from_account = sender.account_id
JOIN customers sender_customer ON sender.customer_id = sender_customer.customer_id
JOIN accounts receiver ON t.to_account = receiver.account_id
JOIN customers receiver_customer ON receiver.customer_id = receiver_customer.customer_id
WHERE t.amount > 10000
ORDER BY t.amount DESC;
-- Smurf ring summary: For all transactions labelled 'smurf', show the from_account, to_account, total amount, and number of transfers between them.
SELECT 
    from_account,
    to_account,
    COUNT(*) AS num_transfers,
    SUM(amount) AS total_amount
FROM transactions
WHERE label = 'smurf'
GROUP BY from_account, to_account
ORDER BY num_transfers DESC, total_amount DESC;

